-- ============================================================================
-- Fase E: Migração de conteúdo institucional (DOCS -> módulos genéricos)
-- Gerado automaticamente a partir do conteúdo já existente em index.html (DOCS)
-- ============================================================================

-- 1. Suportar campos de texto longo (markdown) no motor genérico
ALTER TABLE fields DROP CONSTRAINT IF EXISTS fields_field_type_check;
ALTER TABLE fields ADD CONSTRAINT fields_field_type_check CHECK (field_type IN (
  'text', 'number', 'date', 'checkbox', 'email', 'tel', 'moeda',
  'select', 'multi-select', 'relationship', 'textarea'
));

-- 2. Criar módulo Financeiro (não existia na árvore original)
INSERT INTO modules (name, icon, section, description, type, "order")
VALUES ('Financeiro', '💰', 'Negócio', 'Estrutura financeira, margens, precificação', 'core', 7)
ON CONFLICT (name, section) DO NOTHING;

-- 3. Campos (título + conteúdo) para os módulos que vão receber esse conteúdo
INSERT INTO fields (module_id, field_name, field_type, "order")
SELECT m.id, f.field_name, f.field_type, f.ord
FROM modules m
CROSS JOIN (VALUES
  ('titulo', 'text', 0),
  ('conteudo', 'textarea', 1)
) AS f(field_name, field_type, ord)
WHERE m.name IN ('Quem Somos', 'Marca', 'Processos Internos', 'Contratos', 'Estratégia', 'Financeiro')
AND NOT EXISTS (
  SELECT 1 FROM fields fl WHERE fl.module_id = m.id AND fl.field_name = f.field_name
);

-- 4. Conteúdo real, extraído de DOCS (index.html) preservando o texto original
INSERT INTO records (module_id, data)
VALUES
  ((SELECT id FROM modules WHERE name = 'Quem Somos'), '{"titulo":"Identidade","conteudo":"# FRUTO · Pilar 1 — IDENTIDADE\n### A raiz que dá coerência a tudo\n\n---\n\n## 1. Definição da empresa (a frase-bússola)\n**A oFruto é uma agência criativa e produtora de comunicação — posicionamento e produção de conteúdo para marcas pessoais no digital.**\n\nAjudamos profissionais comuns, pessoas extraordinárias e empresários com um grande bastidor — gente que já construiu coisas excepcionais — a erguer a sua marca no digital a partir daquilo que já são.\n\nDamos o norte dessa comunicação através do **posicionamento** (a junção de tudo que a pessoa é, organizada de um jeito que conversa com o mundo digital) e cuidamos da **embalagem que o público vê** através do **audiovisual** — o vídeo, a imagem, a sensibilidade da lente. Sempre com um objetivo: que isso sirva e impacte diretamente o negócio que a pessoa tem ou vai ter.\n\n## 2. Propósito (por que existimos)\n**Existimos para ajudar cada cliente a gerar fruto no digital.**\n\nGerar fruto é gerar resultado — e o resultado é particular de cada pessoa. Nascemos pra ajudar quem tem sonhos e ambições a realizá-los através dos frutos que geramos: se a pessoa precisa vender mais, o fruto dela é a venda; se precisa ser reconhecida, o fruto é a autoridade.\n\nNo fundo, é revelar a marca que cada pessoa já carrega, transformá-la em referência no digital e fazer dessa referência um negócio. **Começamos no presente e continuamos no futuro.**\n\n## 3. O que nos move (o motor)\n**Ver uma pessoa virar referência e, por isso, poder expandir o seu negócio.**\n\nO que nos move é o *antes e depois de percepção*: ajudar quem tinha valor mas não sabia comunicar a mostrar esse valor ao mundo — e ser reconhecida e procurada pelo que realmente é. Ver mais gente enxergando, escolhendo e comprando dela. É isso que nos dá prazer.\n\n## 4. A tese (o que sustenta o trabalho)\n**Marca não é criada. Marca é revelada.**\n\nUma marca não surge do acaso — ela é o conjunto de vivências, aprendizados e sabedoria de uma pessoa, mostrado ao mundo da maneira certa pra ser amada, desejada e escolhida.\n\n- O **posicionamento** é o alinhamento dessa comunicação — como mostramos isso ao mundo (narrativa, pilares, moodboard, tom de voz, personas, formatos, linha editorial). É a **raiz**.\n- O **audiovisual** é a forma como mostramos visualmente essa raiz — o vídeo, a imagem, a lente. É a **flor** que as pessoas veem.\n- Nosso papel é **arquitetar a marca**: projetar a estrutura (raiz) antes de construir o que aparece (flor).\n\n## 5. O mantra\n**Plantamos estratégia, cultivamos marcas e geramos fruto.**\n- Plantamos estratégia → posicionamento (a raiz)\n- Cultivamos marcas → implementação/audiovisual (o cultivo)\n- Geramos fruto → resultado: demanda, percepção, autoridade, venda\n\n## 6. Manifesto\n> Ninguém precisa virar outra pessoa pra ter uma marca forte.\n> Marca boa não se fabrica — se revela a partir da raiz que já existe.\n>\n> A gente entra antes da câmera. Antes do post. Antes da estética.\n> Primeiro entende quem você é. Depois projeta como o mundo vai te ver.\n>\n> Conteúdo sem raiz é barulho. Marca sem estratégia morre por falta de comunicação, não de qualidade.\n>\n> A oFruto planta estratégia, cultiva marcas e gera fruto."}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Quem Somos'), '{"titulo":"Valores","conteudo":"# Valores e princípios\n\n**1. Raiz antes de flor**\nEstratégia vem antes de estética. Não produzimos nada sem um porquê projetado. Primeiro a estrutura, depois o que aparece. É o nosso princípio de criação.\n\n**2. A marca é da pessoa, não nossa**\nA voz é do cliente. Temos um estilo criativo próprio, mas criamos sempre para alguém — revelamos e amplificamos quem a pessoa já é, nunca sobrescrevemos com a nossa cara.\n\n**3. A gente não cria inverdade**\nConstruímos a partir do real, nunca de um personagem que não se sustenta. Não mascaramos, não inventamos alguém que a pessoa não é pra impressionar. Marca só é forte quando é verdadeira.\n\n**4. Marca se cultiva**\nMarca é como uma planta: precisa regar, arar a terra, ter ritmo, confiança e tempo. Trabalhamos no curto e no longo prazo, porque o processo criativo é um processo de construção — não uma entrega avulsa."}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Estratégia'), '{"titulo":"ICP","conteudo":"# FRUTO · Pilar 3 — COMERCIAL\n## Parte 1: ICP (Perfil de Cliente Ideal)\n\n> ICP = a descrição precisa de quem é o cliente perfeito da oFruto.\n> Serve pra você mirar o marketing, adaptar o discurso e dizer \"não\" pro cliente errado.\n\n---\n\n## O denominador comum (a raiz do cliente ideal)\nAntes dos 3 perfis, o que TODO cliente ideal da oFruto tem em comum:\n\n> **É alguém que já tem valor real — bagagem, resultado, bastidor — mas ainda não sabe (ou não conseguiu) traduzir isso em marca no digital.**\n\nNão é quem quer \"ser famoso\". É quem já é bom no que faz e precisa que o mundo veja isso. Marca a partir de quem a pessoa já é.\n\n**Todos compartilham:**\n- Têm algo genuíno por trás (não é fachada)\n- Querem crescer, mas travam em \"o que postar / como me mostrar\"\n- Enxergam conteúdo como investimento no negócio, não como vaidade\n- Valorizam estratégia (não querem só \"um editor de vídeo\")\n\n---\n\n## PERFIL 1 — O Profissional (médico, advogado, dentista, especialista)\n**Quem é:** referência técnica na sua área, mas invisível ou amador no digital. Tem autoridade no consultório/escritório e zero presença fora dele.\n\n**Dores:**\n- \"Eu sei que preciso aparecer, mas não sei o que falar nem como\"\n- Vê colegas piores tecnicamente crescendo por saberem se comunicar\n- Tem medo de parecer amador ou de se expor errado\n- Não tem tempo nem cabeça pra pensar em conteúdo\n\n**Desejos:**\n- Ser reconhecido como autoridade na área (não só bom de boca a boca)\n- Atrair pacientes/clientes melhores e mais qualificados\n- Ter presença que combine com o nível do trabalho dele\n\n**Gatilho de compra (quando ele procura você):**\n- Perdeu um paciente/caso pra um concorrente mais \"visível\"\n- Vai lançar consultório/serviço próprio\n- Cansou de tentar postar sozinho e não sair do lugar\n\n---\n\n## PERFIL 2 — O Empresário com bastidor forte\n**Quem é:** construiu algo real (empresa, operação, patrimônio), tem histórias e conhecimento, mas nunca transformou isso em marca pessoal. O \"gigante silencioso\".\n\n**Dores:**\n- Tem muito o que dizer, mas acha que \"não é influencer\" e trava\n- Sente que está deixando dinheiro/oportunidade na mesa por não ter marca\n- Não quer virar \"dancinha\", quer algo à altura do que ele é\n- Já tentou terceirizar e ficou genérico, sem a cara dele\n\n**Desejos:**\n- Ser visto como referência/autoridade no seu setor\n- Gerar demanda e oportunidades (parcerias, clientes, investidores)\n- Deixar um legado, uma marca que é extensão da história dele\n\n**Gatilho de compra:**\n- Vai lançar um produto/expandir e precisa de audiência\n- Viu um concorrente/par virar referência e se incomodou\n- Entendeu que a marca pessoal dele vale mais que a da empresa\n\n---\n\n## PERFIL 3 — O Influencer / Criador que quer virar negócio\n**Quem é:** já cria conteúdo, já tem audiência (pequena ou média), mas está preso no \"criador\" e quer virar \"marca/negócio\" — ter produto, autoridade e faturamento.\n\n**Dores:**\n- Cresce em seguidores mas não converte em dinheiro/negócio\n- Conteúdo sem direção estratégica — posta muito, evolui pouco\n- Não sabe como transformar audiência em marca vendável\n- Faz tudo sozinho e está no limite (sem escala nem qualidade)\n\n**Desejos:**\n- Profissionalizar a marca e ter um posicionamento sólido\n- Sair do \"criador\" e virar autoridade com produto próprio\n- Elevar o nível de produção (estética à altura da ambição)\n\n**Gatilho de compra:**\n- Quer lançar um produto/mentoria e precisa de posicionamento\n- Bateu num teto e não sabe como subir de nível sozinho\n- Quer parar de \"postar por postar\" e ter estratégia\n\n---\n\n## O que NÃO é cliente ideal (o anti-ICP)\n- Quem não tem nada real por trás (quer fabricar um personagem)\n- Quem quer resultado mágico e imediato, sem processo\n- Quem quer só um \"editor barato\", não valoriza estratégia\n- Quem não topa se envolver na própria marca\n- Quem quer pular a etapa de posicionamento e ir direto pra produção\n\n---\n\n## Como usar este ICP na prática\n- **No marketing:** fale a dor de um perfil por vez (conteúdo pro médico ≠ conteúdo pro empresário).\n- **Na call:** identifique qual dos 3 perfis está na sua frente e use o gatilho e o desejo dele.\n- **Na proposta:** conecte o serviço ao objetivo real daquele perfil (fruto = venda? autoridade? demanda?)."}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Estratégia'), '{"titulo":"Processo de venda","conteudo":"# FRUTO · Pilar 3 — COMERCIAL\n## Parte 2: Processo Comercial da oFruto\n\n> O SEU processo de venda, registrado. Vale pra qualquer origem de lead.\n> Espinha dorsal: os 7 Passos da Venda (Flávio Augusto), adaptados à oFruto.\n\n---\n\n## 1. Origem do lead (de onde vem gente)\nTodo cliente entra por uma destas 3 portas:\n\n**🤝 Indicação (referral)**\nAlguém gostou do trabalho (ou de você) e indicou. Vem da rede de contato e de clientes satisfeitos.\n→ *Ação da oFruto: pedir indicação ativamente aos clientes atuais.*\n→ **Hoje é a nossa principal origem.**\n\n**🧲 Inbound (marketing de atração)**\nA pessoa vem até nós, atraída por algo que produzimos. A gente se posiciona e é escolhido.\n→ *Ações: produção de conteúdo no perfil pessoal (Davi) e no da agência, panfleto, presença orgânica.*\n→ **É o canal que queremos ativar agora — orgânico, sem tráfego pago.**\n\n**🎯 Outbound (prospecção ativa)**\nA gente vai até a pessoa. Abordagem direta de alguém que ainda não nos procurou.\n→ *Ações: DM, contato direto, lista de possíveis clientes.*\n\n> Independente da porta de entrada, o processo de venda a seguir é o MESMO.\n> Pode rodar por WhatsApp, mas o ideal é **call online** ou uma ligação rápida.\n\n---\n\n## 2. O processo de venda (os 7 passos, do seu jeito)\n\n### Passo 1 — Atrair e conectar\nAtrair pessoas que realmente tenham interesse no que a gente faz e estabelecer conexão.\n- Dar o **norte** de quem é a oFruto e o que fazemos\n- Qualificar rápido\n- Se conectar com a pessoa (quebrar o gelo, criar rapport)\n\n### Passo 2 — Escutar e adaptar (abordagem/diagnóstico)\nEscutar o cliente e adaptar a conversa às dúvidas e características dele.\n- É o primeiro diagnóstico\n- **Objetivo único aqui:** entender **cenário, momento e ideia** — se ele se qualifica ou não\n- Nada de vender ainda. Só entender.\n\n### Passo 3 — Qualificação (fim da Call 1)\nCom base no diagnóstico, decidir:\n- **Se qualifica** (tem fit, momento e condição) → avança pra oferta (Call 2)\n- **Não qualifica** → encerra com honestidade (anti-ICP) ou indica outro caminho\n\n### Passo 4 — Oferta (Call 2 / apresentação)\nA pessoa já vem preparada pra receber a oferta.\n- Retoma a dor dita no diagnóstico\n- Apresenta a solução (Plantio / Pomar / Marca Viva) e por quê\n- Mostra o caminho do **ponto A ao ponto B**\n\n### Passo 5 — Valor e negociação\n- Encanta, agrega valor, vende o sonho (o \"depois de percepção\", o fruto)\n- Conduz as **linhas de negociação** (condições, forma de pagamento, ajustes de escopo)\n\n### Passo 6 — Fechamento\n- A pergunta-chave: **\"Faz sentido pra você?\"**\n- \"Tô dentro\" → fecha na hora → Pix/entrada (destrava o início)\n- Precisa de mais um passo → envia a **proposta por link** (gerador)\n\n### Passo 7 — Pós-venda\n- Confirmação, contrato e início\n- Entra no **Fluxo Pós-Assinatura** (Pilar 4)\n- A relação começa aqui (e é de onde saem novas indicações)\n\n---\n\n## 3. Ferramentas do processo\n- **Proposta:** gerada pelo seu sistema, enviada por link personalizado\n- **Canal:** WhatsApp pra iniciar, call online/ligação pra diagnóstico e oferta\n\n---\n\n## 4. Próximo nível — profissionalizar (o que você quer construir)\n> Registrado como próximos passos, dentro da central de dados:\n\n- ⬜ **CRM / registro de cada lead** — origem (indicação/inbound/outbound), perfil (ICP), em que etapa está\n- ⬜ **Régua de follow-up** — quando e como cobrar retorno (ex.: proposta sem resposta → msg em 2 dias, msg em 4 dias)\n- ⬜ **Pipeline visível** — colunas: Lead → Diagnóstico → Oferta → Proposta enviada → Fechado → Perdido\n- ⬜ **Plano de conteúdo pra inbound** — ativar perfil pessoal + da agência pra atrair organicamente"}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Estratégia'), '{"titulo":"Filtro oFruto","conteudo":"# Filtro de Qualificação — oFruto\n\nFerramenta interna. Decide se uma pessoa é cliente, e para qual plano.\nRoda antes de fechar contrato. Não é diagnóstico de estratégia (isso é outra\nskill, roda depois).\n\n## Como usar\n\nDesce porta por porta, na ordem. Cada porta testa uma condição.\nCada porta tem três saídas possíveis:\n\n- **VERDE** — passa, desce pra próxima.\n- **AMARELO** — serve, mas com ressalva. Anota a ressalva; ela vira cláusula\n  de contrato ou conversa franca antes de fechar. Continua descendo.\n- **VERMELHO** — trava aqui. Não é cliente agora. O motivo do travamento é a\n  informação mais valiosa: diz o que faltou e o que a pessoa precisaria mudar\n  pra voltar a fazer sentido.\n\nUm só VERMELHO em qualquer porta encerra o funil. Os AMARELOS se acumulam:\num sozinho é gerenciável, três ou mais no mesmo cliente é sinal de que o\ncontrato inteiro vai ser trabalhoso — trate como VERMELHO na prática.\n\nAo lado de cada porta, a **fonte**: quem responde. `[você]` = seu julgamento\nobservando a pessoa e o material dela. `[cliente]` = a pessoa te conta, na\nconversa inicial. `[ambos]` = ela conta e você valida.\n\n---\n\n## PORTA 1 — Aparecer (gate inegociável) · fonte [cliente]\n\nA pessoa topa ser o rosto, aparecer na câmera com constância, ao longo de\ntodo o contrato?\n\n- **VERDE** — topa aparecer e entende que a marca é ela.\n- **AMARELO** — topa, mas com receio, timidez, ou \"nunca fiz isso\". Serve: parte\n  do teu trabalho é dirigir quem trava na frente da câmera. Vira ressalva: as\n  primeiras diárias vão ter mais direção e aquecimento.\n- **VERMELHO** — não quer aparecer, quer terceirizar o rosto, quer marca sem\n  cara. Para aqui. O método é audiovisual com a pessoa no centro; sem rosto,\n  não há o que cultivar.\n\n> Por que é a primeira porta: é a mais eliminatória e a mais barata de\n> descobrir. Não faz sentido testar mais nada se isso já trava.\n\n---\n\n## PORTA 2 — Encaixe de nicho · fonte [ambos]\n\nO tipo de negócio e a área da pessoa funcionam com marca pessoal orgânica em\nvídeo?\n\n- **VERDE** — profissional ou fundador cuja autoridade é pessoal e cuja área\n  permite comunicar livremente (a maioria: consultores, profissionais liberais\n  sem trava de conselho, donos de negócio de serviço, criadores).\n- **AMARELO** — nicho com regra de publicidade a respeitar (medicina, odonto,\n  advocacia com limite da OAB, áreas reguladas). Serve, mas a estratégia tem\n  que nascer dentro das regras do conselho de classe. Vira ressalva: alinhar o\n  que pode e o que não pode comunicar antes de qualquer roteiro.\n- **VERMELHO** — negócio onde marca pessoal não é a alavanca (produto físico de\n  prateleira sem rosto por trás, negócio que precisa de performance/tráfego e\n  não de autoridade pessoal, nicho onde aparecer é proibido de fato). Para\n  aqui. Não é que a pessoa é ruim; é que o teu método não é a ferramenta certa\n  pra ela.\n\n---\n\n## PORTA 3 — Substância pra extrair · fonte [você]\n\nJá existe trajetória, autoridade, um ponto de vista, uma verdade própria de\nonde lapidar?\n\n- **VERDE** — tem história, casos, repertório, uma posição sobre a própria\n  área. Há solo pra cavar.\n- **AMARELO** — tem substância, mas pouca ou ainda difusa. Serve, mas a fase\n  Solo vai ser mais longa e mais decisiva; o valor do trabalho estratégico\n  sobe. Vira ressalva: deixar claro que o primeiro mês é mais pesado de\n  extração.\n- **VERMELHO** — início absoluto, sem repertório, sem casos, sem verdade\n  própria. Nada pra extrair de dentro pra fora. Para aqui. Não é o momento —\n  pode voltar quando tiver estrada.\n\n---\n\n## PORTA 4 — Compra a lógica da plantação · fonte [cliente]\n\nEntende que marca orgânica se planta e se cultiva, que o fruto é médio/longo\nprazo, e não viralização sob encomenda?\n\n- **VERDE** — pensa em construção, aceita o horizonte, quer marca e não pico.\n- **AMARELO** — compra a lógica, mas com ansiedade por resultado, ou vindo de\n  uma frustração com tráfego/agência anterior. Serve, mas exige expectativa\n  alinhada por escrito e conversa honesta sobre prazos. Vira ressalva.\n- **VERMELHO** — quer viralizar amanhã, mede sucesso só por número imediato,\n  quer retorno de performance. Para aqui. É cliente de tráfego pago, não seu.\n\n---\n\n## PORTA 5 — Cede a direção · fonte [você]\n\nQuer ser dirigido e confia no processo, ou quer microgerenciar cada corte e\nroteiro?\n\n- **VERDE** — quer direção, respeita teu papel, colabora sem controlar.\n- **AMARELO** — opinativo, participativo demais, mas de boa fé. Serve, mas\n  precisa de um combinado claro de alçadas: o que é decisão dele, o que é tua.\n  Vira ressalva contratual.\n- **VERMELHO** — quer controlar tudo, acha que sabe mais que você sobre a\n  própria comunicação, transforma cada entrega em disputa. Para aqui. Contrato\n  infernal, resultado que não vem, portfólio manchado.\n\n---\n\n## ROTEAMENTO — Qual plano · fonte [ambos]\n\nSó chega aqui quem passou por todas as portas. Agora não é mais \"se\", é \"qual\".\nDuas leituras se cruzam:\n\n### Leitura A — perfil de relação\n\n- Quer subir rápido, é mais independente, topa tocar o próprio feed depois de\n  receber a plantação pronta → tende a **Plantio**.\n- Quer tirar o peso das costas de vez, parceria contínua, você como sócio de\n  comunicação → tende a **Colheita**.\n\n### Leitura B — capacidade financeira (roteador, não porta)\n\nA verba nunca elimina o cliente aqui; ela roteia.\n\n- Tem verba confortável pra recorrência longa sem que o valor machuque →\n  **Colheita** cabe.\n- Tem verba pontual, ou prefere um compromisso menor pra começar → **Plantio**,\n  que tem entrada maior mas horizonte curto e custo total menor.\n- Passa em tudo, mas a verba aperta em qualquer formato → não é VERMELHO, é\n  **\"ainda não\" ou \"começa pelo Plantio\"**. Cliente certo, momento financeiro\n  a amadurecer. Deixa a porta aberta.\n\n> Regra de ouro do roteamento: capacidade de pagar **sem dor** é condição de um\n> bom contrato. Cliente que vai ter que ser perseguido todo mês atrás de\n> pagamento contamina a relação, por melhor que seja em tudo o mais. Isso é\n> AMARELO forte — pesa antes de fechar.\n\n---\n\n## CHEGADA — O veredito\n\nAo fim do percurso, uma de três conclusões:\n\n1. **Serve — Plantio.** Passou nas portas, perfil independente / verba pontual.\n2. **Serve — Colheita.** Passou nas portas, perfil parceria / verba recorrente.\n3. **Não serve agora.** Travou numa porta. O veredito nomeia **qual porta** e\n   **o que mudaria o jogo** — isso é mais forte que uma recusa seca, e mantém a\n   ponte pro futuro.\n\nSome a isso os AMARELOS acumulados: cada um vira uma linha no contrato ou um\nponto da conversa de alinhamento antes da assinatura. Um contrato que nasce\ncom as ressalvas ditas é um contrato que não vira surpresa depois.\n\n---\n\n## Nota pra versão HTML (não é porta)\n\nA **capacidade operacional** (quantos Plantio/Colheita você aguenta ao mesmo\ntempo) não entra como porta, porque é condição tua, não do cliente. Ela vive\nno painel do HTML: o teto operacional aparece ali, e um cliente aprovado pode\nvirar \"fila de espera\" se a agenda estiver cheia — um \"sim, mas a partir de tal\nmês\", nunca um \"não\"."}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Processos Internos'), '{"titulo":"Jurídico","conteudo":"# FRUTO · Pilar 4 — JURÍDICO / OPERACIONAL\n### O que faz a agência rodar sem depender da sua cabeça\n\n---\n\n## 1. Contratos ✅\nModelo-base editável → **Fruto_Contrato_Modelo.md** (campos `{{ }}`, gera por cliente).\n- ⬜ Gerar contrato de cada serviço (Plantio / Pomar / Marca Viva)\n- ⬜ Passar o modelo-base num advogado uma vez (blinda pra sempre)\n- Marca Viva: atenção à sociedade com a Brenda.\n\n## 2. Fluxo de entrega ✅ (geral)\nBase pronta → **Fruto_Fluxo_Pos_Assinatura.md** (8 etapas + 3 gates).\n**Gates inegociáveis:** não produz sem posicionamento aprovado · não publica sem revisão · não renova sem resultado.\n> 🔜 Fluxo DETALHADO por serviço (Plantio/Pomar/Marca Viva têm entregas diferentes) nasce depois da Metodologia. Ver Pilar Metodologia.\n\n## 3. Onboarding ✅ (checklist de início)\nPasta criada · cliente no sistema · boas-vindas · canal definido · briefing enviado · imersão agendada.\n> 🔜 Perguntas de imersão detalhadas nascem da Metodologia.\n\n---\n\n## 4. Capacidade operacional ✅ (a fórmula)\n\n> Capacidade não se mede em nº de clientes — se mede em **HORAS**.\n> Cada serviço consome um tanto de horas/mês. A soma não pode passar do seu teto.\n\n**Horas/mês por serviço (produção + entrega):**\n| Serviço | Horas/mês |\n|---|---|\n| Plantio | 41h |\n| Pomar | 50h |\n| Marca Viva | 33h |\n\n**Teto de referência (por pessoa):** ~220h/mês\n*(comparativo de um CLT: 8h/dia × ~22 dias. Você trabalha mais, mas usar o teto CLT protege você de lotar 100% e virar refém da operação.)*\n\n**A fórmula:**\n> (nº de Plantio × 41) + (nº de Pomar × 50) + (nº de Marca Viva × 33) ≤ teto de horas disponíveis\n\n**Exemplo (o seu):** 3 Pomar + 1 Plantio + 1 Marca Viva\n= (3×50) + (1×41) + (1×33) = **224h** → já está no limite de 1 pessoa (~220h).\nPor isso você sente que \"não consegue ter mais\": a conta bate. O equilíbrio é essa soma.\n\n**Como usar na prática:**\n- Cada serviço tem um **teto individual** também (ex.: quantos Pomar cabem se eu só fizer Pomar → 220 ÷ 50 ≈ 4).\n- Ao fechar novo cliente, some as horas. Chegou perto do teto? → **sobe preço** ou **contrata** (freela de edição/gravação é o 1º a entrar, pra devolver horas suas).\n- Com a Brenda somando horas, o teto do time dobra (~440h) — mas isso entra quando a sociedade estiver estruturada.\n\n**Gatilho de contratação:** ao bater ~80% do teto de forma recorrente, entra o 1º freela.\n\n---\n\n## 5. Onde tudo mora (gestão) ✅ (direção definida)\n- **Gestão de clientes/projetos:** dentro de um **site hospedado da própria oFruto** (a central Fruto). Já existe uma base — **falta melhorar/evoluir**. ⟵ EM CONSTRUÇÃO\n- **Estrutura de pasta padrão por cliente** (onde ficam os arquivos brutos/finais):\n  - `01_Estratégia` · `02_Roteiros` · `03_Bruto` · `04_Editado` · `05_Aprovações` · `06_Contrato_Financeiro`\n- **O que a central precisa ter pra gerir de verdade:** lista de clientes, status/etapa de cada um, horas consumidas (pra bater na capacidade), contratos e propostas gerados, próximos passos.\n\n---\n\n## 6. Modelos que agilizam\n- ✅ Contrato · ✅ Fluxo pós-assinatura\n- 🔜 Briefing de imersão (nasce da Metodologia)\n- 🔜 Checklist de produção por serviço (nasce da Metodologia)\n- ⬜ Modelo de relatório de performance"}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Contratos'), '{"titulo":"Contrato modelo","conteudo":"# FRUTO · Modelo de Contrato (editável)\n### Prestação de Serviços de Posicionamento e Produção de Conteúdo\n\n> **Como usar:** os campos entre `{{ }}` são os variáveis — preencha por cliente\n> (a mesma lógica do seu gerador de propostas). O resto é a base fixa.\n>\n> ⚠️ **Importante:** este é um modelo-base para agilizar, não um parecer jurídico.\n> Antes de usar de verdade, peça a um advogado pra revisar e adaptar à sua realidade\n> (principalmente cláusulas de rescisão, propriedade intelectual e valores). Não sou advogado.\n\n---\n\n**CONTRATO DE PRESTAÇÃO DE SERVIÇOS**\n\n**CONTRATADA:** {{razao_social_ofruto}}, inscrita no CNPJ nº {{cnpj_ofruto}}, com sede em {{endereco_ofruto}}, doravante denominada **CONTRATADA**.\n\n**CONTRATANTE:** {{nome_cliente}}, {{cpf_ou_cnpj_cliente}}, com endereço em {{endereco_cliente}}, doravante denominado **CONTRATANTE**.\n\nAs partes acima têm, entre si, justo e contratado o seguinte:\n\n---\n\n### Cláusula 1 — Objeto\nA CONTRATADA prestará ao CONTRATANTE serviços de **{{servico_contratado}}** (ex.: Semente / Cultivo / Safra), conforme escopo detalhado no **Anexo I (Escopo de Entrega)**, que é parte integrante deste contrato.\n\n### Cláusula 2 — Escopo e entregas\n2.1. As entregas específicas, quantidades e formatos estão descritos no Anexo I.\n2.2. Serviços fora do escopo descrito serão orçados à parte, mediante aprovação prévia do CONTRATANTE.\n2.3. **Não estão incluídos:** {{itens_nao_incluidos}} (ex.: tráfego pago, deslocamentos fora de {{cidade}}, equipamentos de terceiros).\n\n### Cláusula 3 — Prazo\n3.1. Este contrato tem vigência de **{{vigencia}}** (ex.: 3 meses), iniciando em {{data_inicio}}.\n3.2. Renovação automática por igual período, salvo aviso de {{prazo_aviso}} dias por qualquer das partes. *(ajuste conforme preferir)*\n\n### Cláusula 4 — Valores e pagamento\n4.1. Valor total/mensal: **R$ {{valor}}** ({{valor_extenso}}).\n4.2. Forma de pagamento: {{forma_pagamento}} (ex.: {{percentual_entrada}}% de entrada + saldo em {{parcelas}}x, vencimento todo dia {{dia_vencimento}}).\n4.3. Atraso superior a {{dias_atraso}} dias autoriza a suspensão dos serviços até a regularização.\n4.4. Reajuste anual pelo {{indice_reajuste}} (ex.: IPCA), se aplicável.\n\n### Cláusula 5 — Obrigações da CONTRATADA\n- Executar os serviços com qualidade e dentro dos prazos acordados.\n- Manter o CONTRATANTE informado do andamento.\n- Respeitar a identidade e a voz do CONTRATANTE.\n- Zelar pelo sigilo das informações recebidas.\n\n### Cláusula 6 — Obrigações do CONTRATANTE\n- Fornecer informações, acessos e materiais necessários no prazo solicitado.\n- Aprovar (ou solicitar ajustes) das entregas em até {{prazo_aprovacao}} dias.\n- Efetuar os pagamentos nas datas combinadas.\n- **Prazos dependentes do cliente:** atrasos na entrega de material ou aprovação estendem os prazos na mesma proporção.\n\n### Cláusula 7 — Rodadas de revisão\nCada entrega inclui até **{{num_revisoes}}** rodadas de ajustes. Revisões adicionais serão orçadas à parte.\n\n### Cláusula 8 — Propriedade intelectual e uso de imagem\n8.1. Após a quitação, os conteúdos entregues pertencem ao CONTRATANTE para uso {{uso_conteudo}} (ex.: nas redes sociais dele).\n8.2. A CONTRATADA pode usar os trabalhos em seu **portfólio e redes**, salvo objeção expressa do CONTRATANTE em {{clausula_portfolio}}.\n8.3. O CONTRATANTE autoriza o uso de sua imagem/material para fins de execução do contrato.\n\n### Cláusula 9 — Confidencialidade\nAs partes se comprometem a manter sigilo sobre informações estratégicas e dados trocados durante a relação, inclusive após o término do contrato.\n\n### Cláusula 10 — LGPD\nAs partes tratarão dados pessoais conforme a Lei nº 13.709/2018, usando-os apenas para a execução deste contrato.\n\n### Cláusula 11 — Rescisão\n11.1. Qualquer parte pode rescindir mediante aviso de {{prazo_rescisao}} dias.\n11.2. Em caso de rescisão, serão devidos os valores proporcionais aos serviços já executados.\n11.3. Rescisão por descumprimento pode ocorrer imediatamente, sem prejuízo de eventuais penalidades: {{multa_rescisoria}}.\n\n### Cláusula 12 — Disposições gerais\n12.1. Este contrato representa o acordo integral entre as partes.\n12.2. Alterações só valem por escrito e assinadas por ambas.\n12.3. Foro eleito: comarca de {{comarca}}.\n\n---\n\nE, por estarem de acordo, assinam:\n\n{{cidade}}, {{data}}.\n\n<br>\n\n______________________________\n**CONTRATADA** — {{razao_social_ofruto}}\n\n<br>\n\n______________________________\n**CONTRATANTE** — {{nome_cliente}}\n\n---\n\n## Anexo I — Escopo de Entrega ({{servico_contratado}})\n*Puxe daqui do seu catálogo de serviços já pronto:*\n- {{entrega_1}}\n- {{entrega_2}}\n- {{entrega_3}}\n- Prazo de cada entrega: {{prazos}}\n- Formato de comunicação/aprovação: {{canal}}\n\n---\n\n### Campos variáveis (referência rápida pra automatizar na central)\n`razao_social_ofruto, cnpj_ofruto, endereco_ofruto, nome_cliente, cpf_ou_cnpj_cliente, endereco_cliente, servico_contratado, itens_nao_incluidos, cidade, vigencia, data_inicio, prazo_aviso, valor, valor_extenso, forma_pagamento, percentual_entrada, parcelas, dia_vencimento, dias_atraso, indice_reajuste, prazo_aprovacao, num_revisoes, uso_conteudo, clausula_portfolio, prazo_rescisao, multa_rescisoria, comarca, data, entrega_1, entrega_2, entrega_3, prazos, canal`"}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Processos Internos'), '{"titulo":"Fluxo pós-venda","conteudo":"# FRUTO · Fluxo Pós-Assinatura\n### Do \"cliente assinou\" ao \"entregando com ritmo\"\n\n> O caminho que todo cliente atravessa depois do sim. Serve pra ninguém ficar perdido\n> e pra a experiência ser a mesma pra todo mundo. Ajuste os prazos à sua realidade.\n\n---\n\n## Etapa 0 — Assinatura e pagamento\n**Objetivo:** oficializar e destravar o início.\n- [ ] Contrato assinado pelas duas partes\n- [ ] 1ª parcela / entrada paga (ou combinada) — *só inicia após confirmação*\n- [ ] Cliente adicionado no seu sistema de gestão (Notion/Trello/etc.)\n- [ ] Pasta do cliente criada (drive) com estrutura padrão\n\n## Etapa 1 — Boas-vindas (primeiras 24–48h)\n**Objetivo:** o cliente sentir que fez a escolha certa.\n- [ ] Mensagem de boas-vindas (o que vem agora, prazos, canal de contato)\n- [ ] Definir canal oficial de comunicação (evita mensagem em 3 lugares)\n- [ ] Enviar formulário/briefing de imersão (perguntas sobre quem ele é, objetivo, referências, o que ama/odeia)\n- [ ] Agendar a reunião de imersão\n\n## Etapa 2 — Imersão / Diagnóstico\n**Objetivo:** entender profundamente quem é o cliente (a base do posicionamento).\n- [ ] Reunião de imersão realizada\n- [ ] Coleta de material (fotos, vídeos, marca existente, acessos)\n- [ ] Alinhar objetivo real do cliente (demanda? percepção? autoridade? venda?)\n- [ ] Definir expectativa: o que é sucesso pra ele nos próximos meses\n\n## Etapa 3 — Estratégia / Posicionamento (a raiz)\n**Objetivo:** entregar o mapa antes de produzir.\n- [ ] Narrativa e tese da marca pessoal\n- [ ] Pilares de conteúdo\n- [ ] Tom de voz + personas\n- [ ] Moodboard / direção estética\n- [ ] Linha editorial e formatos\n- [ ] **Apresentação do posicionamento ao cliente + aprovação**\n\n## Etapa 4 — Produção / Audiovisual (a flor)\n**Objetivo:** transformar estratégia em conteúdo.\n- [ ] Roteiros / ideias / temas aprovados\n- [ ] Agenda de gravação definida\n- [ ] Produção (gravação + edição)\n- [ ] Revisão interna (qualidade antes de mandar)\n- [ ] Aprovação do cliente\n\n## Etapa 5 — Publicação / Ritmo\n**Objetivo:** manter a colheita constante.\n- [ ] Calendário de postagem definido\n- [ ] Conteúdo publicado (por você ou pelo cliente)\n- [ ] Rotina mensal rodando (roteiro → produção → publicação)\n\n## Etapa 6 — Acompanhamento / Prestação de contas\n**Objetivo:** provar que o conteúdo trabalha pelo objetivo.\n- [ ] Métricas acompanhadas (alcance, salvamentos, demanda gerada)\n- [ ] Reunião/relatório periódico (mensal recomendado)\n- [ ] Ajustes de rota com base no que funcionou\n\n## Etapa 7 — Renovação / Evolução\n**Objetivo:** transformar cliente em relação de longo prazo.\n- [ ] Avaliar resultado do ciclo\n- [ ] Proposta de renovação ou próximo passo (ex.: Semente → Cultivo)\n- [ ] Pedir depoimento / autorização de case\n\n---\n\n## Marcos que valem virar \"gate\" (não avança sem)\n- Não inicia produção **sem posicionamento aprovado**.\n- Não publica **sem revisão interna**.\n- Não renova **sem mostrar resultado**.\n\n## Dica de organização\nCada cliente é um \"card\" no seu sistema, com essas etapas como checklist.\nBateu o olho → você sabe exatamente em que ponto cada cliente está."}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Financeiro'), '{"titulo":"Financeiro","conteudo":"# FRUTO · Pilar 5 — FINANCEIRO\n### Versão real da sua fase: solo, começando, faturamento comprometido\n\n> Nada de planilha de empresa grande que não é a sua realidade.\n> Aqui está o financeiro do jeito que ele é HOJE — e o caminho pra evoluir.\n\n---\n\n## 1. Foto atual (com seus contratos reais)\n\n| Contrato | Valor/mês | Observação |\n|---|---|---|\n| Deputado federal | R$ 5.500 | ~3º mês. Pode não renovar após a eleição (outubro) |\n| Brenda | R$ 2.500 | |\n| Amanda Sobottka | R$ 1.200 | |\n| EMEDE (loja MD) | R$ 1.200 | |\n| **TOTAL** | **R$ 10.400/mês** | |\n\n### ⚠️ O alerta mais importante da central\n**Sem o deputado, o faturamento cai para R$ 4.900/mês.**\nQuase metade da receita depende de 1 contrato com data pra possivelmente acabar (out).\n\n> **Meta financeira nº 1:** repor (e superar) os R$ 5.500 com novos contratos ANTES de outubro.\n> Isso conecta direto com o Comercial (Pilar 3): ativar inbound + pedir indicação agora.\n\n---\n\n## 2. A verdade da fase (sem romantizar)\n- Você é **solo** — sem funcionário. ✅ normal pra começar.\n- **Todo o faturamento é comprometido** com contas pessoais + carro.\n- **Não há caixa/reserva ainda.** ✅ normal — a gente constrói.\n- Custos hoje: basicamente **alguns softwares no cartão**, sem controle formal.\n\nIsso não é problema. É ponto de partida. O objetivo do Pilar 5 nesta fase é simples:\n**ter clareza, não ter contabilidade.**\n\n---\n\n## 3. Os 3 números que você precisa saber (só esses por enquanto)\n\n**a) Quanto você precisa pra viver (seu piso):** R$ {{ }}/mês ⟵ DEFINIR\n*O total das suas contas pessoais fixas. É o mínimo que a oFruto tem que te pagar.*\n\n**b) Quanto entra hoje:** R$ 10.400 (→ R$ 4.900 pós-outubro)\n\n**c) Quanto sai de custo da empresa:** R$ {{ }}/mês\n*Só some os softwares/cartão que são da operação. Provavelmente baixo — mas anote, pra saber.*\n\n> Com esses 3 números você já sabe se está no azul e quanto de folga tem. Só isso já é um upgrade enorme.\n\n---\n\n## 4. Os 3 movimentos práticos desta fase (não precisa mais que isso)\n\n**Movimento 1 — Anotar (custa 0 e muda tudo)**\nUma nota simples (celular ou papel) com: o que entrou, o que saiu, o que sobrou no mês.\nSem planilha bonita. Só o hábito. 5 minutos por mês.\n\n**Movimento 2 — Repor o deputado antes de outubro**\nMeta clara: +R$ 5.500 em novos contratos até out. É a prioridade comercial nº 1.\n\n**Movimento 3 — O carro quita mês que vem → nasce seu primeiro respiro**\nA parcela que liberar, não some no consumo. Guarde ao menos uma parte.\nEsse é o embrião da sua reserva. Mesmo R$ 200–300/mês já começa.\n\n---\n\n## 5. O GATILHO de estruturação (a régua que define quando)\n\n> **Regra:** o momento de estruturar o financeiro \"de empresa\" é quando você ultrapassar\n> o seu PISO DE VIDA (o quanto custa manter seu estilo de vida hoje).\n\n- **Enquanto:** o que entra ≈ o que você precisa pra viver → foco em CLAREZA + REPOR receita.\n- **No mês em que:** entrar **mais do que o piso de vida** → esse excedente é lucro real → aciona a estruturação.\n\n**Diferença que não pode confundir:**\n- **Pró-labore** = seu salário / piso de vida. É um CUSTO da empresa (a empresa te paga primeiro).\n- **Lucro** = o que sobra DEPOIS do pró-labore e dos custos. Fica na empresa (reserva, reinvestir, crescer).\n- É o **lucro** (não o seu salário) que financia contratar e crescer.\n\n**Situação do CNPJ:** já aberto — falta **regularizar**. Fica pra quando acionar o gatilho.\n\n**Checklist da estruturação (dispara quando ultrapassar o piso de vida):**\n- ⬜ Regularizar CNPJ + abrir conta PJ (separar empresa de pessoal)\n- ⬜ Definir pró-labore fixo = seu piso de vida\n- ⬜ Montar reserva (1–3 meses de contas)\n- ⬜ Calcular margem e lucro/hora por serviço (cruzar com capacidade do Pilar 4)\n- ⬜ Aí sim: contratar (1º freela de edição/gravação pra devolver suas horas)"}'::jsonb),
  ((SELECT id FROM modules WHERE name = 'Marca'), '{"titulo":"Marca & Ativos","conteudo":"# FRUTO · Pilar 6 — MARCA / ATIVOS\n### O inventário do que a oFruto mostra ao mundo\n\n---\n\n## 1. Identidade visual 🟡 (em evolução — decisões tomadas)\n- **Nome/marca:** oFruto — agência criativa e produtora de comunicação\n- **Favicon:** ⬜ TROCAR — vou usar um novo (nó de marca que criei) no lugar do atual. Atualizar no site também.\n- **Direção estética (mantida e refinada):**\n  - Base **preto e branco**\n  - **Verde entra via imagens** (capim, natureza, verde) como cor de contraste — não como cor chapada\n  - **Fonte:** Poppins (ou similar) em **peso mais grosso / espessura alta**\n  - Uso do logo: mantido\n- **Mantra:** \"Plantamos estratégia, cultivamos marcas e geramos fruto\"\n- *Obs: identidade criada por você mesmo (sem designer por ora). Ajustes finos ficam pro futuro.*\n\n## 2. Presença digital\n> Regra do Davi: **\"pra mim agora tudo é site\"** — a preferência é sempre página hospedada com link.\n\n- **Site institucional:** 🟡 REFAZER — o atual está ruim. Refazer com base no que já tem + a referência que você já possui (coisa rápida, sem reinventar).\n- **Link na bio (perfil pessoal + agência):** ⬜ criar/organizar (aponta pro site/portfólio/contato)\n- **Página Sobre (missão + valores):** *observação: você não lembra de ter — checar. Se não existe, entra no site novo.*\n- **Central \"Fruto\":** ✅🟡 site hospedado onde mora TUDO isto (o Heart). Já existe base com sistema operacional (CRM, demanda de cliente, envio/aprovação de conteúdo) — **falta melhorar**.\n- **Instagram agência @agenciaofruto:** ✅ existe — ⬜ ativar conteúdo (depende de criar o posicionamento da agência)\n- **Instagram pessoal @davimourx:** ✅ existe — ⬜ ativar conteúdo (depende de criar a arquitetura de marca do Davi)\n- **Domínio ofruto.com:** ✅\n\n## 3. Portfólio (a prova) ⬜ CRIAR\n- Formato: **site hospedado com link** (pra mandar e a pessoa já ver)\n- Conteúdo: os cases/resultados reais (50k, 31k, 115k views; EMEDE, Amanda, Brenda, deputado)\n- Formato de case: *cliente → desafio → o que fizemos → resultado (número)*\n- ⬜ Pedir autorização de uso (nome/imagem) — atenção aos sensíveis (político)\n\n## 4. Material comercial\n- **Gerador de proposta:** ✅\n- **Modelo de contrato:** ✅\n- **Mídia kit / apresentação (quem somos + serviços + cases):** ⬜ criar — pode ser **site institucional** (preferência) ou PDF\n\n## 5. Ativos internos ✅\n- A central/Heart (Pilares 1 a 6) ✅ · 🔜 Pilar Metodologia\n- Modelos: contrato ✅, fluxo pós-assinatura ✅\n\n---\n\n## O que precisa ser CRIADO agora (lista limpa)\n1. ⬜ Novo favicon (trocar no site atual)\n2. ⬜ Refazer o site institucional\n3. ⬜ Portfólio (site com link)\n4. ⬜ Mídia kit (site ou PDF)\n5. ⬜ Link na bio (pessoal + agência)\n6. ⬜ Melhorar a central Fruto (sistema operacional)\n7. ⬜ Ativar os 2 Instagram (depende de posicionamento)"}'::jsonb);
